{"path": "grep.py", "content": "def grep(pattern, flags, files):
    if isinstance(flags, str):
        flags = flags.split()
    flags = set(flags or [])
    multi = len(files) > 1
    needle = pattern.lower() if "-i" in flags else pattern
    out = []
    for name in files:
        found = False
        with open(name, encoding="utf-8") as f:
            for num, raw in enumerate(f, 1):
                line = raw.rstrip("\r\n")
                hay = line.lower() if "-i" in flags else line
                hit = hay == needle if "-x" in flags else needle in hay
                if "-v" in flags:
                    hit = not hit
                if not hit:
                    continue
                found = True
                if "-l" in flags:
                    break
                prefix = ""
                if multi:
                    prefix += name + ":"
                if "-n" in flags:
                    prefix += str(num) + ":"
                out.append(prefix + line + "\n")
        if "-l" in flags and found:
            out.append(name + "\n")
    return "".join(out)
